<script setup lang="ts">
import { paletteEntries, normalizeHex, normalizePalette, resolveColor, tones, toneLabels, type Palette } from '@qinbian/shared'
const props=defineProps<{palette?:Palette;mappings?:Record<string,string>;current?:string;title?:string}>(),emit=defineEmits<{close:[];choose:[choice:{token?:string;value:string}]}>(),ctx=useQinbian()
const tab=ref<'theme'|'custom'>('theme'),custom=ref(normalizeHex(props.current||'')||'#183a49'),p=computed(()=>normalizePalette(props.palette))
function choose(token:string){emit('choose',{token,value:resolveColor(token,p.value,props.mappings)})}
function apply(){const value=normalizeHex(custom.value);if(!value){ctx.notify('请输入 #RRGGBB 格式的色值',true);return}emit('choose',{value})}
</script>
<template><UiModal :title="title||'文字颜色'" subtitle="主题色随映射调整；自定义只改变当前选中的内容。" @close="emit('close')"><div class="tab-line color-tabs"><button :class="{active:tab==='theme'}" @click="tab='theme'">主题色 · 映射关系</button><button :class="{active:tab==='custom'}" @click="tab='custom'">自定义</button></div><div v-if="tab==='theme'" class="color-chooser"><div class="tone-headers"><span/><span v-for="tone in tones" :key="tone">{{toneLabels[tone]}}</span></div><div v-for="c in p.colors" :key="c.id" class="color-choice-row"><span>{{c.name}}<small>{{c.id}}</small></span><button v-for="tone in tones" :key="tone" :aria-label="c.name+' '+toneLabels[tone]" :title="`${c.id}-${tone} · ${c[tone]}`" @click="choose(`${c.id}-${tone}`)"><i :style="{background:resolveColor(`${c.id}-${tone}`,p,mappings)}"/><small>{{c[tone]}}</small></button></div></div><div v-else class="custom-color-panel"><input v-model="custom" type="color" aria-label="自定义颜色"><label>色值<input v-model="custom" aria-label="自定义颜色色值" placeholder="#183A49"></label><div class="modal-actions"><button class="btn primary" @click="apply">采用此颜色</button></div></div></UiModal></template>
